export interface WebAPKifyConfig {
    appName: string;
    appId: string;
    versionCode?: number;
    versionName?: string;
    artifact?: string;
    webDir?: string;
    minSdk?: number;
    compileSdk?: number;
    targetSdk?: number;
    buildToolsVersion?: string;
    icon?: string;
    adaptiveIconForeground?: string;
    monochromeIcon?: string;
    adaptiveIconBackground?: string;
    webview?: {
        javaScriptEnabled?: boolean;
        javaScriptCanOpenWindowsAutomatically?: boolean;
        domStorageEnabled?: boolean;
        databaseEnabled?: boolean;
        geolocationEnabled?: boolean;
        allowMixedContent?: boolean;
        builtInZoomControls?: boolean;
        displayZoomControls?: boolean;
        userAgentString?: string;
        allowFileAccessFromFileURLs?: boolean;
        allowUniversalAccessFromFileURLs?: boolean;
        textZoom?: number;
        loadsImagesAutomatically?: boolean;
        blockNetworkImage?: boolean;
        blockNetworkLoads?: boolean;
        cacheMode?: 'DEFAULT' | 'CACHE_ELSE_NETWORK' | 'NO_CACHE' | 'CACHE_ONLY';
        loadWithOverviewMode?: boolean;
        useWideViewPort?: boolean;
        mediaPlaybackRequiresUserGesture?: boolean;
        safeBrowsingEnabled?: boolean;
        forceDark?: 'OFF' | 'ON' | 'AUTO';
        algorithmicDarkeningAllowed?: boolean;
        acceptCookies?: boolean;
        acceptThirdPartyCookies?: boolean;
    };
    permissions?: {
        internet?: boolean;
        networkState?: boolean;
        wifiState?: boolean;
        coarseLocation?: boolean;
        fineLocation?: boolean;
        camera?: boolean;
        recordAudio?: boolean;
        readExternalStorage?: boolean;
        writeExternalStorage?: boolean;
        readMediaImages?: boolean;
        readMediaVideo?: boolean;
        readMediaAudio?: boolean;
        vibrate?: boolean;
        receiveBootCompleted?: boolean;
        postNotifications?: boolean;
        bluetooth?: boolean;
        nfc?: boolean;
        biometric?: boolean;
        fingerprint?: boolean;
        flashlight?: boolean;
        wakeLock?: boolean;
        foregroundService?: boolean;
        scheduleExactAlarm?: boolean;
    };
    orientation?: string;
    statusBar?: 'default' | 'light' | 'dark' | 'transparent';
    themeColor?: string;
    backgroundColor?: string;
    allowBackup?: boolean;
    hardwareAccelerated?: boolean;
    keepScreenOn?: boolean;
    supportsRtl?: boolean;
    restoreAnyVersion?: boolean;
    clearTextDomains?: string[];
    allowAllClearText?: boolean;
    signing?: {
        storeFile: string;
        storePassword: string;
        keyAlias: string;
        keyPassword: string;
        v1SigningEnabled?: boolean;
        v2SigningEnabled?: boolean;
        v3SigningEnabled?: boolean;
        v4SigningEnabled?: boolean;
    };
    build?: {
        minifyEnabled?: boolean;
        shrinkResources?: boolean;
        jvmTarget?: string;
        kotlinVersion?: string;
        agpVersion?: string;
        extraProperties?: Record<string, string>;
    };
}
